import React, { Component } from 'react';
import './About.css';

class About extends Component {
  constructor(props) {
    super(props);
    this.state = {
      skills: [
        'JavaScript',
        'React',
        'Node.js',
        'HTML5',
        'CSS3',
        'Python',
        'Git',
        'MongoDB',
        'SQL',
      ],
    };
  }

  render() {
    return (
      <div className="about-section">
        <div className="about-container">
          <div className="about-image-wrapper">
            <div className="about-image-placeholder">
              Your Photo
            </div>
          </div>
          <div className="about-content">
            <h2 className="about-title">About Me</h2>
            <p className="about-description">
              <h2>Welcome to my personal profile!</h2>
              Hi! Im a Senior pursuing my B.S. in Data Science with a Business Minor at NJIT, and part of the BS-MS program where I'll earn my M.S. in Artificial Intelligence by 2027.
              I’m passionate about the intersection of data, technology, and finance — leveraging analytics to drive smarter, more efficient business decisions. As a Financial Analyst Intern with the New Jersey Courts, I’ve developed dashboards, reconciled large transactional datasets, and streamlined operations through data-driven insights.
              Beyond finance, I’ve led and developed AI and data engineering projects, managing SQL databases and deploying machine learning models that transform complex data into actionable intelligence. This combination of technical expertise and business understanding helps me bridge communication between data teams and strategic stakeholders.
              I’m excited about opportunities in data analytics, financial analytics, business intelligence, and data engineering — roles where I can use data storytelling and technology to shape impactful business outcomes
            </p>
            <p className="about-description">
              When I am not coding, I like to explore new tools and contribute to
              open-source projects. Feel free to browse my portfolio and get in touch.
            </p>
            <div className="about-skills">
              <h3 className="about-skills-title">Skills & Technology</h3>
              <div className="about-skills-list">
                {this.state.skills.map((skill, index) => (
                  <span key={index} className="about-skill-tag">{skill}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

export default About;
